import sys

def findRollNumber(rollNumbers, target):
    left, right = 0, len(rollNumbers) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if rollNumbers[mid] == target:
            return mid

        if rollNumbers[left] <= rollNumbers[mid]:
            if rollNumbers[left] <= target < rollNumbers[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if rollNumbers[mid] < target <= rollNumbers[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

